import json
d=json.load(open("tools/registry.json"))
rows=d["rows"]; by={r["name"]:r for r in rows}
st={}
for r in rows: st[r["status"]]=st.get(r["status"],0)+1
print("statuses=",st)
bad=[]
for r in rows:
    if r["status"]!="active":
        t=r.get("superseded_by")
        ok = r["status"]=="superseded" and t in by and by[t]["status"]=="active"
        print("NONACTIVE",r["name"],"status=",r["status"],"superseded_by=",t,"target_status=",by.get(t,{}).get("status"),"ok=",ok)
        if not ok: bad.append(r["name"])
    elif "superseded_by" in r: bad.append(r["name"]+":active-with-superseded_by")
print("invariant_violations=",bad)
